insert into public.questions (id, kind, prompt, options, marks) values ('41f86618-8185-5313-8267-1158f3667644', 'mcq', 'Match each prokaryotic structure to its function.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('41f86618-8185-5313-8267-1158f3667644', 2, 'Wall: stops bursting. Pili: attachment and plasmid transfer. Flagellum: movement. Plasmid: extra genes. Capsule: protection and adhesion.', 'movement') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
