insert into public.questions (id, kind, prompt, options, marks) values ('82b27ada-2771-51d5-8999-cb4e8b8a8108', 'short', 'The cells in Figure 3 are about 2 µm long. Explain why a light microscope cannot show their ribosomes. [2]', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('82b27ada-2771-51d5-8999-cb4e8b8a8108', 'Ribosomes are about 20–25 nm across [1], far smaller than the resolution of a light microscope (about 200 nm), so they cannot be distinguished [1].', 'Ribosomes are about 20–25 nm across [1], far smaller than the resolution of a light microscope (about 200 nm), so they cannot be distinguished [1].', '[{"text": "Marking point 1", "any": ["resolution", "200 nm", "0.2"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["ribosome", "small", "20", "nm"], "all": [], "marks": 1}]'::jsonb, 'Ribosomes are about 20–25 nm across [1], far smaller than the resolution of a light microscope (about 200 nm), so they cannot be distinguished [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
