insert into public.questions (id, kind, prompt, options, marks) values ('25fd0ca4-e070-56c0-a237-14704b3171ab', 'short', 'Describe the structure of a prokaryotic cell. [4]', '[]'::jsonb, 4) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('25fd0ca4-e070-56c0-a237-14704b3171ab', 'Cell wall of peptidoglycan [1]; circular, naked DNA in a nucleoid region [1]; 70S ribosomes in the cytoplasm [1]; no nucleus or membrane-bound organelles, and may have plasmids, pili, flagella or a capsule [1].', 'Cell wall of peptidoglycan [1]; circular, naked DNA in a nucleoid region [1]; 70S ribosomes in the cytoplasm [1]; no nucleus or membrane-bound organelles, and may have plasmids, pili, flagella or a capsule [1].', '[{"text": "Marking point 1", "any": ["cell wall", "peptidoglycan"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["nucleoid", "circular", "naked"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["70s", "ribosome"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["no nucleus", "no membrane-bound", "no organelle", "plasmid", "flagell", "pili", "capsule"], "all": [], "marks": 1}]'::jsonb, 'Cell wall of peptidoglycan [1]; circular, naked DNA in a nucleoid region [1]; 70S ribosomes in the cytoplasm [1]; no nucleus or membrane-bound organelles, and may have plasmids, pili, flagella or a capsule [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('46a51a04-40b6-5532-b3d5-3503ca979ed6', '25fd0ca4-e070-56c0-a237-14704b3171ab', 14);
