insert into public.questions (id, kind, prompt, options, marks) values ('26f5720d-191c-5d2e-99cc-3b9cddc066b3', 'mcq', 'Match each organelle to its main function.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('26f5720d-191c-5d2e-99cc-3b9cddc066b3', 2, 'Mitochondrion: respiration. Rough ER: protein synthesis. Golgi: modifies and packages. Lysosome: digestion. Chloroplast: photosynthesis. Nucleus: chromosomes.', 'modifies and packages proteins') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
