insert into public.questions (id, kind, prompt, options, marks) values ('a2c08543-0a3d-5aba-891a-a05dba09109b', 'short', 'Explain two advantages of compartmentalisation in eukaryotic cells. [2]', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('a2c08543-0a3d-5aba-891a-a05dba09109b', 'Enzymes and substrates can be concentrated in one compartment, making reactions more efficient [1]; harmful or incompatible reactions are kept apart, for example digestive enzymes inside lysosomes, and each compartment can have its own conditions such as pH [1].', 'Enzymes and substrates can be concentrated in one compartment, making reactions more efficient [1]; harmful or incompatible reactions are kept apart, for example digestive enzymes inside lysosomes, and each compartment can have its own conditions such as pH [1].', '[{"text": "Marking point 1", "any": ["concentrat", "efficien", "faster"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["separate", "apart", "protect", "harmful", "different condition", "ph"], "all": [], "marks": 1}]'::jsonb, 'Enzymes and substrates can be concentrated in one compartment, making reactions more efficient [1]; harmful or incompatible reactions are kept apart, for example digestive enzymes inside lysosomes, and each compartment can have its own conditions such as pH [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('46a51a04-40b6-5532-b3d5-3503ca979ed6', 'a2c08543-0a3d-5aba-891a-a05dba09109b', 18);
insert into public.questions (id, kind, prompt, options, marks) values ('901c8645-e2a4-5430-a497-c7c49c351da2', 'mcq', 'How does Paramecium carry out each process?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('901c8645-e2a4-5430-a497-c7c49c351da2', 0, 'Nutrition: food vacuoles. Movement: cilia. Homeostasis: contractile vacuoles. Reproduction: binary fission. Response: reversing from obstacles.', 'food vacuoles digest ingested food') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
