insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('8c878b04-ee99-50d7-a580-5388c2e38449', 4, 'Nutrition: food vacuoles. Movement: cilia. Homeostasis: contractile vacuoles. Reproduction: binary fission. Response: reversing from obstacles.', 'reverses when it hits an obstacle') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
