insert into public.questions (id, kind, prompt, options, marks) values ('f5b02939-88de-5f17-9274-99c574f09c0d', 'short', 'Compare how Paramecium and Chlamydomonas obtain their nutrition. [2]', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('f5b02939-88de-5f17-9274-99c574f09c0d', 'Paramecium is a heterotroph: it ingests food into food vacuoles and digests it [1]; Chlamydomonas is an autotroph: it makes its own food by photosynthesis in its chloroplast [1].', 'Paramecium is a heterotroph: it ingests food into food vacuoles and digests it [1]; Chlamydomonas is an autotroph: it makes its own food by photosynthesis in its chloroplast [1].', '[{"text": "Marking point 1", "any": ["heterotroph", "ingest", "food vacuole", "engulf"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["autotroph", "photosynth", "chloroplast"], "all": [], "marks": 1}]'::jsonb, 'Paramecium is a heterotroph: it ingests food into food vacuoles and digests it [1]; Chlamydomonas is an autotroph: it makes its own food by photosynthesis in its chloroplast [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('46a51a04-40b6-5532-b3d5-3503ca979ed6', 'f5b02939-88de-5f17-9274-99c574f09c0d', 21);
insert into public.questions (id, kind, prompt, options, marks) values ('b9d4d453-ccdf-576f-8a80-634abd2fe01f', 'short', 'Outline how a unicellular organism carries out four of the processes of life. [4]', '[]'::jsonb, 4) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('b9d4d453-ccdf-576f-8a80-634abd2fe01f', 'Nutrition: food vacuoles (Paramecium) or photosynthesis in the chloroplast (Chlamydomonas) [1]; movement: cilia or flagella [1]; homeostasis: contractile vacuoles remove excess water, and wastes such as CO₂ diffuse out [1]; reproduction by binary fission, or response such as moving towards light using the eyespot [1].', 'Nutrition: food vacuoles (Paramecium) or photosynthesis in the chloroplast (Chlamydomonas) [1]; movement: cilia or flagella [1]; homeostasis: contractile vacuoles remove excess water, and wastes such as CO₂ diffuse out [1]; reproduction by binary fission, or response such as moving towards light using the eyespot [1].', '[{"text": "Marking point 1", "any": ["nutrition", "food vacuole", "photosynth"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["movement", "cilia", "flagell"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["homeostasis", "contractile", "excret"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["reproduc", "binary fission", "response", "eyespot"], "all": [], "marks": 1}]'::jsonb, 'Nutrition: food vacuoles (Paramecium) or photosynthesis in the chloroplast (Chlamydomonas) [1]; movement: cilia or flagella [1]; homeostasis: contractile vacuoles remove excess water, and wastes such as CO₂ diffuse out [1]; reproduction by binary fission, or response such as moving towards light using the eyespot [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('46a51a04-40b6-5532-b3d5-3503ca979ed6', 'b9d4d453-ccdf-576f-8a80-634abd2fe01f', 22);
insert into public.questions (id, kind, prompt, options, marks) values ('feef55bc-f9bd-5096-8969-ec76a5bb5841', 'mcq', 'Which cell type?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('feef55bc-f9bd-5096-8969-ec76a5bb5841', 0, 'Chitin wall: fungus. No wall, centrioles: animal. Cellulose wall and chloroplasts, starch: plant.', 'Plant') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('46a51a04-40b6-5532-b3d5-3503ca979ed6', 'feef55bc-f9bd-5096-8969-ec76a5bb5841', 23);
insert into public.questions (id, kind, prompt, options, marks) values ('950fe882-b384-5594-a121-a51dc9b8e838', 'mcq', 'Match each atypical cell to the reason it is atypical.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('950fe882-b384-5594-a121-a51dc9b8e838', 3, 'Muscle fibre: fused cells, many nuclei. Hypha: no septa, many nuclei. Red blood cell: no nucleus. Sieve tube: no nucleus, relies on a companion cell.', 'no nucleus, depends on a companion cell') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('46a51a04-40b6-5532-b3d5-3503ca979ed6', '950fe882-b384-5594-a121-a51dc9b8e838', 24);
insert into public.questions (id, kind, prompt, options, marks) values ('79877e3a-1e5d-535f-ba92-6d1f5d65fac2', 'short', 'Explain why skeletal muscle fibres challenge the idea that a cell is a unit with one nucleus. [2]', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('79877e3a-1e5d-535f-ba92-6d1f5d65fac2', 'A muscle fibre has many nuclei [1] because it forms from the fusion of many cells into one long continuous structure, so it is not a typical unit of one nucleus in one membrane [1].', 'A muscle fibre has many nuclei [1] because it forms from the fusion of many cells into one long continuous structure, so it is not a typical unit of one nucleus in one membrane [1].', '[{"text": "Marking point 1", "any": ["many nuclei", "multinucleate", "several nuclei"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["fus", "continuous", "one cell", "single"], "all": [], "marks": 1}]'::jsonb, 'A muscle fibre has many nuclei [1] because it forms from the fusion of many cells into one long continuous structure, so it is not a typical unit of one nucleus in one membrane [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('46a51a04-40b6-5532-b3d5-3503ca979ed6', '79877e3a-1e5d-535f-ba92-6d1f5d65fac2', 25);
insert into public.questions (id, kind, prompt, options, marks) values ('e907408b-8151-57ec-8657-e74680dbe6d1', 'short', 'State four conventions for a biological drawing. [4]', '[]'::jsonb, 4) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e907408b-8151-57ec-8657-e74680dbe6d1', 'Use a sharp pencil [1]; clear continuous single lines [1]; no shading [1]; ruled label lines that do not cross, with a title and the magnification or a scale bar [1].', 'Use a sharp pencil [1]; clear continuous single lines [1]; no shading [1]; ruled label lines that do not cross, with a title and the magnification or a scale bar [1].', '[{"text": "Marking point 1", "any": ["pencil"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["single line", "continuous", "clear line", "no sketch"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["no shading", "shade"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["ruled", "ruler", "label line", "not cross", "title", "scale", "magnification"], "all": [], "marks": 1}]'::jsonb, 'Use a sharp pencil [1]; clear continuous single lines [1]; no shading [1]; ruled label lines that do not cross, with a title and the magnification or a scale bar [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
