insert into public.questions (id, kind, prompt, options, marks) values ('b3c6f484-f29a-50d5-acf0-42a66595cf81', 'short', 'Compare and contrast the structure of plant cells and fungal cells. [3]', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('b3c6f484-f29a-50d5-acf0-42a66595cf81', 'Both have a cell wall, nucleus and often a large vacuole [1]; the plant wall is cellulose but the fungal wall is chitin [1]; plants have chloroplasts and store starch, fungi have no chloroplasts and store glycogen [1].', 'Both have a cell wall, nucleus and often a large vacuole [1]; the plant wall is cellulose but the fungal wall is chitin [1]; plants have chloroplasts and store starch, fungi have no chloroplasts and store glycogen [1].', '[{"text": "Marking point 1", "any": ["both", "similar", "cell wall", "vacuole", "nucleus"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["cellulose", "chitin"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["chloroplast", "starch", "glycogen"], "all": [], "marks": 1}]'::jsonb, 'Both have a cell wall, nucleus and often a large vacuole [1]; the plant wall is cellulose but the fungal wall is chitin [1]; plants have chloroplasts and store starch, fungi have no chloroplasts and store glycogen [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('46a51a04-40b6-5532-b3d5-3503ca979ed6', 'b3c6f484-f29a-50d5-acf0-42a66595cf81', 27);
insert into public.questions (id, kind, prompt, options, marks) values ('dff23746-0742-5a89-a5d8-392ec66c1ec8', 'mcq', 'Is each feature evidence that mitochondria were once bacteria?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('dff23746-0742-5a89-a5d8-392ec66c1ec8', 1, 'Evidence: circular naked DNA, 70S ribosomes, double membrane, binary fission. Being in all eukaryotes or making ATP does not by itself show a bacterial origin.', 'Not evidence on its own') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('46a51a04-40b6-5532-b3d5-3503ca979ed6', 'dff23746-0742-5a89-a5d8-392ec66c1ec8', 28);
insert into public.questions (id, kind, prompt, options, marks) values ('16b3041a-b308-523e-b312-ad27bf1c91cf', 'mcq', 'A beta cell in the pancreas makes insulin, but a skin cell does not. Why?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('16b3041a-b308-523e-b312-ad27bf1c91cf', 1, 'Both cells have the insulin gene; only the beta cell expresses it.', 'The insulin gene is expressed in the beta cell but not in the skin cell') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
