insert into public.questions (id, kind, prompt, options, marks) values ('fbeede96-6757-5b25-b8cf-f081971d9e6d', 'mcq', 'Put the possible stages of the evolution of multicellularity in order.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('fbeede96-6757-5b25-b8cf-f081971d9e6d', 3, 'Single cells → colony → division of labour (somatic and reproductive cells, as in Volvox) → many interdependent cell types.', '4th') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('46a51a04-40b6-5532-b3d5-3503ca979ed6', 'fbeede96-6757-5b25-b8cf-f081971d9e6d', 30);
