insert into public.questions (id, kind, prompt, options, marks) values ('a9f85361-ed28-5d07-8320-f8965d93e19d', 'mcq', 'Inductive or deductive reasoning?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('a9f85361-ed28-5d07-8320-f8965d93e19d', 0, 'Observations → general rule = inductive (1 and 3). General rule → prediction = deductive (2 and 4).', 'Inductive') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
