insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('b0189db5-c634-5848-88d6-93bdd148edaf', 1, 'Observations → general rule = inductive (1 and 3). General rule → prediction = deductive (2 and 4).', 'Deductive') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
