insert into public.questions (id, kind, prompt, options, marks) values ('be3d3479-9355-583d-aa27-c39a08ee3855', 'short', 'Distinguish between magnification and resolution. [2]', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('be3d3479-9355-583d-aa27-c39a08ee3855', 'Magnification is how many times larger the image is than the actual object [1]; resolution is the ability to distinguish two points close together as separate, which determines the detail seen [1].', 'Magnification is how many times larger the image is than the actual object [1]; resolution is the ability to distinguish two points close together as separate, which determines the detail seen [1].', '[{"text": "Marking point 1", "any": ["how many times", "larger", "bigger", "enlarg"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["detail", "distinguish", "separate", "two points"], "all": [], "marks": 1}]'::jsonb, 'Magnification is how many times larger the image is than the actual object [1]; resolution is the ability to distinguish two points close together as separate, which determines the detail seen [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('748db3e8-5835-56a8-b7cd-fee4c109255b', 'be3d3479-9355-583d-aa27-c39a08ee3855', 3);
insert into public.questions (id, kind, prompt, options, marks) values ('84c7c40d-636f-5ebf-9759-0da41e5f14dc', 'mcq', 'Light microscope, electron microscope or both?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('84c7c40d-636f-5ebf-9759-0da41e5f14dc', 0, 'Living cells and 0.2 µm resolution: light. Ribosomes and vacuum: electron. Both produce magnified images.', 'Light microscope') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('748db3e8-5835-56a8-b7cd-fee4c109255b', '84c7c40d-636f-5ebf-9759-0da41e5f14dc', 4);
