insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('cfb0bf80-1991-59e0-961e-c3a70d5a42aa', 2, 'Immunofluorescence: locates specific proteins. Freeze-fracture: splits membranes. Cryo-EM: 3D protein structures.', 'builds 3D structures of proteins from frozen samples') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('748db3e8-5835-56a8-b7cd-fee4c109255b', 'cfb0bf80-1991-59e0-961e-c3a70d5a42aa', 6);
insert into public.questions (id, kind, prompt, options, marks) values ('b03fac70-aac9-50db-9afd-decca45b32d0', 'short', 'Explain how immunofluorescence shows the location of a protein in a cell. [3]', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('b03fac70-aac9-50db-9afd-decca45b32d0', 'Antibodies specific to the protein are made [1]; a fluorescent dye is attached to the antibodies [1]; they bind only where the protein is, which glows under UV light, showing its location [1].', 'Antibodies specific to the protein are made [1]; a fluorescent dye is attached to the antibodies [1]; they bind only where the protein is, which glows under UV light, showing its location [1].', '[{"text": "Marking point 1", "any": ["antibod"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["fluoresc", "dye", "glow"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["specific", "binds", "bind", "attach"], "all": [], "marks": 1}]'::jsonb, 'Antibodies specific to the protein are made [1]; a fluorescent dye is attached to the antibodies [1]; they bind only where the protein is, which glows under UV light, showing its location [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('748db3e8-5835-56a8-b7cd-fee4c109255b', 'b03fac70-aac9-50db-9afd-decca45b32d0', 7);
insert into public.questions (id, kind, prompt, options, marks) values ('17ec3a3c-8d64-5a12-8c65-a3bcd8a5958e', 'short', 'Outline why the electron microscope changed our understanding of cell structure. [2]', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('17ec3a3c-8d64-5a12-8c65-a3bcd8a5958e', 'Its much higher resolution (about 1000 times better than light) [1] revealed the ultrastructure of cells, such as ribosomes, membranes and the inside of organelles [1].', 'Its much higher resolution (about 1000 times better than light) [1] revealed the ultrastructure of cells, such as ribosomes, membranes and the inside of organelles [1].', '[{"text": "Marking point 1", "any": ["resolution", "detail"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["ultrastructure", "ribosome", "membrane", "organelle", "smaller"], "all": [], "marks": 1}]'::jsonb, 'Its much higher resolution (about 1000 times better than light) [1] revealed the ultrastructure of cells, such as ribosomes, membranes and the inside of organelles [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('748db3e8-5835-56a8-b7cd-fee4c109255b', '17ec3a3c-8d64-5a12-8c65-a3bcd8a5958e', 8);
insert into public.questions (id, kind, prompt, options, marks) values ('21bec006-9ef6-551b-8f22-3ce2990b2451', 'mcq', 'Match each structure common to all cells to its function.
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('21bec006-9ef6-551b-8f22-3ce2990b2451', 0, 'Membrane: controls entry and exit. Cytoplasm: metabolism. DNA: genetic information. Ribosomes: protein synthesis.', 'controls what enters and leaves') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('748db3e8-5835-56a8-b7cd-fee4c109255b', '21bec006-9ef6-551b-8f22-3ce2990b2451', 9);
insert into public.questions (id, kind, prompt, options, marks) values ('2e7d4e42-4169-53d3-8e10-7e9f9e3f477f', 'mcq', 'Found in ALL prokaryotes, or only in SOME?
insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('2e7d4e42-4169-53d3-8e10-7e9f9e3f477f', 0, 'All: cell wall (in most bacteria), 70S ribosomes, nucleoid DNA. Some: plasmids, flagellum, capsule.', 'All prokaryotes') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
insert into public.quiz_questions (quiz_id, question_id, position) values ('748db3e8-5835-56a8-b7cd-fee4c109255b', '2e7d4e42-4169-53d3-8e10-7e9f9e3f477f', 10);
