insert into public.questions (id, kind, prompt, options, marks) values ('31a4408e-1a0f-5273-abc3-8c7fbe6dbbb9', 'short', 'Explain what is meant by "naked DNA" in prokaryotes. [2]', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('31a4408e-1a0f-5273-abc3-8c7fbe6dbbb9', 'The DNA is not associated with (wrapped around) histone proteins [1], unlike eukaryotic chromosomes; it lies free in the nucleoid of the cytoplasm [1].', 'The DNA is not associated with (wrapped around) histone proteins [1], unlike eukaryotic chromosomes; it lies free in the nucleoid of the cytoplasm [1].', '[{"text": "Marking point 1", "any": ["histone", "protein"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["not", "no", "without"], "all": [], "marks": 1}]'::jsonb, 'The DNA is not associated with (wrapped around) histone proteins [1], unlike eukaryotic chromosomes; it lies free in the nucleoid of the cytoplasm [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('748db3e8-5835-56a8-b7cd-fee4c109255b', '31a4408e-1a0f-5273-abc3-8c7fbe6dbbb9', 12);
