insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('8b2b87f3-8da8-55f1-ab3d-3f40fe0beeae', 3, 'Mitochondrion: respiration. Rough ER: protein synthesis. Golgi: modifies and packages. Lysosome: digestion. Chloroplast: photosynthesis. Nucleus: chromosomes.', 'digests old organelles') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
