insert into public.questions (id, kind, prompt, options, marks) values ('f5b02939-88de-5f17-9274-99c574f09c0d', 'short', 'Compare how Paramecium and Chlamydomonas obtain their nutrition. [2]', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('f5b02939-88de-5f17-9274-99c574f09c0d', 'Paramecium is a heterotroph: it ingests food into food vacuoles and digests it [1]; Chlamydomonas is an autotroph: it makes its own food by photosynthesis in its chloroplast [1].', 'Paramecium is a heterotroph: it ingests food into food vacuoles and digests it [1]; Chlamydomonas is an autotroph: it makes its own food by photosynthesis in its chloroplast [1].', '[{"text": "Marking point 1", "any": ["heterotroph", "ingest", "food vacuole", "engulf"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["autotroph", "photosynth", "chloroplast"], "all": [], "marks": 1}]'::jsonb, 'Paramecium is a heterotroph: it ingests food into food vacuoles and digests it [1]; Chlamydomonas is an autotroph: it makes its own food by photosynthesis in its chloroplast [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('748db3e8-5835-56a8-b7cd-fee4c109255b', 'f5b02939-88de-5f17-9274-99c574f09c0d', 23);
insert into public.questions (id, kind, prompt, options, marks) values ('b9d4d453-ccdf-576f-8a80-634abd2fe01f', 'short', 'Outline how a unicellular organism carries out four of the processes of life. [4]', '[]'::jsonb, 4) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('b9d4d453-ccdf-576f-8a80-634abd2fe01f', 'Nutrition: food vacuoles (Paramecium) or photosynthesis in the chloroplast (Chlamydomonas) [1]; movement: cilia or flagella [1]; homeostasis: contractile vacuoles remove excess water, and wastes such as CO₂ diffuse out [1]; reproduction by binary fission, or response such as moving towards light using the eyespot [1].', 'Nutrition: food vacuoles (Paramecium) or photosynthesis in the chloroplast (Chlamydomonas) [1]; movement: cilia or flagella [1]; homeostasis: contractile vacuoles remove excess water, and wastes such as CO₂ diffuse out [1]; reproduction by binary fission, or response such as moving towards light using the eyespot [1].', '[{"text": "Marking point 1", "any": ["nutrition", "food vacuole", "photosynth"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["movement", "cilia", "flagell"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["homeostasis", "contractile", "excret"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["reproduc", "binary fission", "response", "eyespot"], "all": [], "marks": 1}]'::jsonb, 'Nutrition: food vacuoles (Paramecium) or photosynthesis in the chloroplast (Chlamydomonas) [1]; movement: cilia or flagella [1]; homeostasis: contractile vacuoles remove excess water, and wastes such as CO₂ diffuse out [1]; reproduction by binary fission, or response such as moving towards light using the eyespot [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('748db3e8-5835-56a8-b7cd-fee4c109255b', 'b9d4d453-ccdf-576f-8a80-634abd2fe01f', 24);
