insert into public.question_answers (question_id, correct_option, explanation, model_answer) values ('cfd615e9-a6f2-525d-abfc-11ebda09d419', 1, 'Muscle fibre: fused cells, many nuclei. Hypha: no septa, many nuclei. Red blood cell: no nucleus. Sieve tube: no nucleus, relies on a companion cell.', 'many nuclei, no cross-walls') on conflict (question_id) do update set correct_option = excluded.correct_option, explanation = excluded.explanation, model_answer = excluded.model_answer;
