insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('79877e3a-1e5d-535f-ba92-6d1f5d65fac2', 'A muscle fibre has many nuclei [1] because it forms from the fusion of many cells into one long continuous structure, so it is not a typical unit of one nucleus in one membrane [1].', 'A muscle fibre has many nuclei [1] because it forms from the fusion of many cells into one long continuous structure, so it is not a typical unit of one nucleus in one membrane [1].', '[{"text": "Marking point 1", "any": ["many nuclei", "multinucleate", "several nuclei"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["fus", "continuous", "one cell", "single"], "all": [], "marks": 1}]'::jsonb, 'A muscle fibre has many nuclei [1] because it forms from the fusion of many cells into one long continuous structure, so it is not a typical unit of one nucleus in one membrane [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
