insert into public.questions (id, kind, prompt, options, marks) values ('b3c6f484-f29a-50d5-acf0-42a66595cf81', 'short', 'Compare and contrast the structure of plant cells and fungal cells. [3]', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('b3c6f484-f29a-50d5-acf0-42a66595cf81', 'Both have a cell wall, nucleus and often a large vacuole [1]; the plant wall is cellulose but the fungal wall is chitin [1]; plants have chloroplasts and store starch, fungi have no chloroplasts and store glycogen [1].', 'Both have a cell wall, nucleus and often a large vacuole [1]; the plant wall is cellulose but the fungal wall is chitin [1]; plants have chloroplasts and store starch, fungi have no chloroplasts and store glycogen [1].', '[{"text": "Marking point 1", "any": ["both", "similar", "cell wall", "vacuole", "nucleus"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["cellulose", "chitin"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["chloroplast", "starch", "glycogen"], "all": [], "marks": 1}]'::jsonb, 'Both have a cell wall, nucleus and often a large vacuole [1]; the plant wall is cellulose but the fungal wall is chitin [1]; plants have chloroplasts and store starch, fungi have no chloroplasts and store glycogen [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
