insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('b9bd70eb-0e34-54ed-b10f-d51e11c2bbea', 'Many thylakoid membranes, stacked in grana [1], give a large area for photosystems with chlorophyll to absorb light for the light-dependent reactions [1]; the stroma contains the enzymes of the Calvin cycle [1].', 'Many thylakoid membranes, stacked in grana [1], give a large area for photosystems with chlorophyll to absorb light for the light-dependent reactions [1]; the stroma contains the enzymes of the Calvin cycle [1].', '[{"text": "Marking point 1", "any": ["thylakoid", "grana"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["photosystem", "chlorophyll", "surface area", "light"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["stroma", "calvin", "enzyme"], "all": [], "marks": 1}]'::jsonb, 'Many thylakoid membranes, stacked in grana [1], give a large area for photosystems with chlorophyll to absorb light for the light-dependent reactions [1]; the stroma contains the enzymes of the Calvin cycle [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
