insert into public.quiz_questions (quiz_id, question_id, position) values ('56c0a956-5836-550c-9ebd-f8d2ba30c081', '8474e23c-c24f-5bee-a6e0-bea6367297d1', 19);
insert into public.questions (id, kind, prompt, options, marks) values ('d22e5c7a-2962-50ac-9675-db3b2e5e46fb', 'short', 'Compare and contrast the structure of mitochondria and chloroplasts. [4]', '[]'::jsonb, 4) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('d22e5c7a-2962-50ac-9675-db3b2e5e46fb', 'Both have a double membrane [1]; both contain 70S ribosomes and circular DNA [1]; mitochondria have an inner membrane folded into cristae, chloroplasts have thylakoids in grana [1]; mitochondria have a matrix (protons in the intermembrane space), chloroplasts a stroma (protons in the thylakoid lumen) [1].', 'Both have a double membrane [1]; both contain 70S ribosomes and circular DNA [1]; mitochondria have an inner membrane folded into cristae, chloroplasts have thylakoids in grana [1]; mitochondria have a matrix (protons in the intermembrane space), chloroplasts a stroma (protons in the thylakoid lumen) [1].', '[{"text": "Marking point 1", "any": ["double membrane", "both"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["70s", "circular", "dna", "ribosome"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["crista", "thylakoid"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["matrix", "stroma", "intermembrane", "lumen"], "all": [], "marks": 1}]'::jsonb, 'Both have a double membrane [1]; both contain 70S ribosomes and circular DNA [1]; mitochondria have an inner membrane folded into cristae, chloroplasts have thylakoids in grana [1]; mitochondria have a matrix (protons in the intermembrane space), chloroplasts a stroma (protons in the thylakoid lumen) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('56c0a956-5836-550c-9ebd-f8d2ba30c081', 'd22e5c7a-2962-50ac-9675-db3b2e5e46fb', 20);
