insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('1a3565d8-33b3-5213-b041-1fb9bca94403', 'The mRNA can be modified (post-transcriptional modification, e.g. removing introns) inside the nucleus [1] before it reaches ribosomes, so only processed mRNA is translated [1].', 'The mRNA can be modified (post-transcriptional modification, e.g. removing introns) inside the nucleus [1] before it reaches ribosomes, so only processed mRNA is translated [1].', '[{"text": "Marking point 1", "any": ["modif", "process", "splic", "intron", "edit"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["before", "ribosome", "translat", "not translated"], "all": [], "marks": 1}]'::jsonb, 'The mRNA can be modified (post-transcriptional modification, e.g. removing introns) inside the nucleus [1] before it reaches ribosomes, so only processed mRNA is translated [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
