insert into public.questions (id, kind, prompt, options, marks) values ('0b01aabc-91b1-5425-b21f-d6834d16bcb8', 'short', 'Explain how lysosomes and phagocytic vacuoles allow a white blood cell to destroy bacteria safely. [3]', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
