insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('ac9fd68f-a72c-5995-8ff3-b65282a10640', 'Pluripotent stem cells can differentiate into any type of body cell (e.g. early embryo cells) [1]; multipotent stem cells can differentiate into only a few related types (e.g. bone marrow cells make blood cells) [1].', 'Pluripotent stem cells can differentiate into any type of body cell (e.g. early embryo cells) [1]; multipotent stem cells can differentiate into only a few related types (e.g. bone marrow cells make blood cells) [1].', '[{"text": "Marking point 1", "any": ["any type of body cell", "all body cell"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["related", "small number", "limited range"], "all": [], "marks": 1}]'::jsonb, 'Pluripotent stem cells can differentiate into any type of body cell (e.g. early embryo cells) [1]; multipotent stem cells can differentiate into only a few related types (e.g. bone marrow cells make blood cells) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
