insert into public.questions (id, kind, prompt, options, marks) values ('4ad3c5e8-6c81-5ea7-b866-23be3ecd5678', 'short', 'Explain how type II pneumocytes are adapted to their function.', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('4ad3c5e8-6c81-5ea7-b866-23be3ecd5678', 'Their cytoplasm contains many secretory vesicles (lamellar bodies) [1] that release surfactant, which reduces surface tension so alveoli do not collapse or stick together during exhalation [1].', 'Their cytoplasm contains many secretory vesicles (lamellar bodies) [1] that release surfactant, which reduces surface tension so alveoli do not collapse or stick together during exhalation [1].', '[{"text": "Marking point 1", "any": ["lamellar", "vesicles", "secretory"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["surface tension", "stops collapse", "prevent collapse", "not collapse", "stick together"], "all": [], "marks": 1}]'::jsonb, 'Their cytoplasm contains many secretory vesicles (lamellar bodies) [1] that release surfactant, which reduces surface tension so alveoli do not collapse or stick together during exhalation [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
