insert into public.questions (id, kind, prompt, options, marks) values ('58135fc8-2067-5c2d-a0be-ff585ba5565c', 'short', 'Discuss whether a striated muscle fibre should be called a cell.', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('58135fc8-2067-5c2d-a0be-ff585ba5565c', 'For: it is surrounded by a single continuous plasma membrane and functions as one unit [1]. Against: it has many nuclei, whereas a typical cell has one [1]; it forms by the fusion of many embryonic cells, so it is better seen as an exception to cell theory [1].', 'For: it is surrounded by a single continuous plasma membrane and functions as one unit [1]. Against: it has many nuclei, whereas a typical cell has one [1]; it forms by the fusion of many embryonic cells, so it is better seen as an exception to cell theory [1].', '[{"text": "Marking point 1", "any": ["one membrane", "single membrane", "surrounded by a membrane", "continuous membrane", "one unit"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["many nuclei", "multinucleate", "more than one nucleus"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["fused", "fusion", "several cells", "many cells"], "all": [], "marks": 1}]'::jsonb, 'For: it is surrounded by a single continuous plasma membrane and functions as one unit [1]. Against: it has many nuclei, whereas a typical cell has one [1]; it forms by the fusion of many embryonic cells, so it is better seen as an exception to cell theory [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('9df65de7-bce5-5be6-8df0-a8dcd2f4b979', '58135fc8-2067-5c2d-a0be-ff585ba5565c', 26);
