insert into public.questions (id, kind, prompt, options, marks) values ('de94ca3e-2899-5d49-91c0-62507fe47a25', 'short', 'Compare the adaptations of human sperm and egg cells.', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('de94ca3e-2899-5d49-91c0-62507fe47a25', 'Both are haploid, carrying one set of chromosomes [1]; the sperm is small and streamlined with a flagellum and many mitochondria to swim, whereas the egg is large with cytoplasm and nutrients for the embryo [1]; the sperm has an acrosome with enzymes, while the egg has a zona pellucida and cortical granules to prevent polyspermy [1].', 'Both are haploid, carrying one set of chromosomes [1]; the sperm is small and streamlined with a flagellum and many mitochondria to swim, whereas the egg is large with cytoplasm and nutrients for the embryo [1]; the sperm has an acrosome with enzymes, while the egg has a zona pellucida and cortical granules to prevent polyspermy [1].', '[{"text": "Marking point 1", "any": ["both haploid", "haploid"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["sperm is small", "egg is large", "larger"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["flagellum", "acrosome", "cortical granules", "zona"], "all": [], "marks": 1}]'::jsonb, 'Both are haploid, carrying one set of chromosomes [1]; the sperm is small and streamlined with a flagellum and many mitochondria to swim, whereas the egg is large with cytoplasm and nutrients for the embryo [1]; the sperm has an acrosome with enzymes, while the egg has a zona pellucida and cortical granules to prevent polyspermy [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('9df65de7-bce5-5be6-8df0-a8dcd2f4b979', 'de94ca3e-2899-5d49-91c0-62507fe47a25', 30);
