insert into public.quizzes (id, title, instructions, time_limit_minutes, max_attempts, published, show_results, category, feedback_mode, created_by) values ('a87dcca3-799e-5a7a-b697-0d85f76d5872', 'B2.3 Cell specialization · Topic quiz (SL)', 'Topic quiz for B2.3 Cell specialization, DP1 Term 1 (SL). Questions come from the interactive lessons. Written answers are marked against the mark scheme; your teacher checks every mark.', null, 2, false, true, 'quiz', 'hybrid', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set title = excluded.title, instructions = excluded.instructions;
insert into public.questions (id, kind, prompt, options, marks) values ('26d6aed6-605c-5485-a275-866a7ef1115c', 'short', 'State the two properties of stem cells.', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('26d6aed6-605c-5485-a275-866a7ef1115c', 'They can divide endlessly (self-renewal) [1]; they can differentiate along different pathways into specialised cell types [1].', 'They can divide endlessly (self-renewal) [1]; they can differentiate along different pathways into specialised cell types [1].', '[{"text": "Marking point 1", "any": ["divide", "self-renew", "self renew", "endless", "unlimited", "mitosis"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["differentiate", "specialise", "specialize", "different pathways", "different types"], "all": [], "marks": 1}]'::jsonb, 'They can divide endlessly (self-renewal) [1]; they can differentiate along different pathways into specialised cell types [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
