insert into public.questions (id, kind, prompt, options, marks) values ('95e1d079-8339-5ec6-99c0-17a1c24eef2a', 'short', 'Explain how gradients of signalling chemicals in an early embryo lead to different cell types.', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('95e1d079-8339-5ec6-99c0-17a1c24eef2a', 'Signalling chemicals (morphogens) form concentration gradients across the embryo [1]; each cell receives a different concentration depending on its position [1]; this switches on different genes, so cells differentiate along different pathways [1].', 'Signalling chemicals (morphogens) form concentration gradients across the embryo [1]; each cell receives a different concentration depending on its position [1]; this switches on different genes, so cells differentiate along different pathways [1].', '[{"text": "Marking point 1", "any": ["gradient", "concentration differs", "different concentrations"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["position", "where", "location"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["gene expression", "genes switched on", "express different genes", "genes expressed", "switch", "different genes"], "all": [], "marks": 1}]'::jsonb, 'Signalling chemicals (morphogens) form concentration gradients across the embryo [1]; each cell receives a different concentration depending on its position [1]; this switches on different genes, so cells differentiate along different pathways [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
