insert into public.questions (id, kind, prompt, options, marks) values ('da82423b-4126-5b90-8fd3-503367981e93', 'short', 'Explain why cells cannot keep growing larger.', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('da82423b-4126-5b90-8fd3-503367981e93', 'As a cell grows, its volume increases faster than its surface area, so the SA:V ratio falls [1]; the need for exchange (O₂, nutrients, waste) depends on volume [1]; but the rate of exchange depends on surface area, and diffusion distances to the centre increase, so exchange becomes too slow for the cell''s needs [1].', 'As a cell grows, its volume increases faster than its surface area, so the SA:V ratio falls [1]; the need for exchange (O₂, nutrients, waste) depends on volume [1]; but the rate of exchange depends on surface area, and diffusion distances to the centre increase, so exchange becomes too slow for the cell''s needs [1].', '[{"text": "Marking point 1", "any": ["volume increases faster", "volume increases more", "ratio decreases", "ratio falls", "ratio gets smaller"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["use depends on volume"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["not enough surface", "diffusion too slow", "distance", "too slow"], "all": [], "marks": 1}]'::jsonb, 'As a cell grows, its volume increases faster than its surface area, so the SA:V ratio falls [1]; the need for exchange (O₂, nutrients, waste) depends on volume [1]; but the rate of exchange depends on surface area, and diffusion distances to the centre increase, so exchange becomes too slow for the cell''s needs [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('a87dcca3-799e-5a7a-b697-0d85f76d5872', 'da82423b-4126-5b90-8fd3-503367981e93', 22);
