insert into public.questions (id, kind, prompt, options, marks) values ('2fdf3847-7f0e-5391-9b8b-bef62541328c', 'short', 'Agar cubes of side 1 cm and 3 cm containing a pH indicator are placed in acid. Predict and explain which cube changes colour all the way through first.', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('2fdf3847-7f0e-5391-9b8b-bef62541328c', 'The 1 cm cube changes colour all the way through first [1]; it has a higher SA:V ratio (6:1 compared with 2:1), so relatively more surface for acid to enter [1]; and the distance from the surface to the centre is shorter, so diffusion reaches the centre sooner [1].', 'The 1 cm cube changes colour all the way through first [1]; it has a higher SA:V ratio (6:1 compared with 2:1), so relatively more surface for acid to enter [1]; and the distance from the surface to the centre is shorter, so diffusion reaches the centre sooner [1].', '[{"text": "Marking point 1", "any": ["1 cm", "smaller", "small cube"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["higher sa:v", "larger sa:v", "bigger ratio", "more surface", "higher ratio", "larger ratio"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["distance", "shorter", "diffuse", "diffusion"], "all": [], "marks": 1}]'::jsonb, 'The 1 cm cube changes colour all the way through first [1]; it has a higher SA:V ratio (6:1 compared with 2:1), so relatively more surface for acid to enter [1]; and the distance from the surface to the centre is shorter, so diffusion reaches the centre sooner [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
